/**
 * A re-plan proposal: a new plan version for a changed orientation, with an honest summary of how much moved.
 *
 * ADR-0010: a re-plan is not an edit. It is generated by the same deterministic planner, it starts today (the past is
 * untouchable), its invariants are re-checked, and the diff it carries reports the change count honestly - `diffPlans`
 * truncates at two changes and sets `changeCountWithinLimit: false`, and this module surfaces that fact instead of
 * pretending the truncation is the whole change.
 *
 * This module proposes and never opens, decides or stores: the review that offers this option, and the runner who
 * accepts it, are elsewhere.
 */
import type { AthleteProfile, PlanVersion } from "@training-planner/domain";
import type { KnowledgeBundle } from "@training-planner/knowledge";
import { addDays, checkInvariants, diffPlans, generatePlan, weekStart } from "@training-planner/planner-core";
import type { Evidence, PlanDiff } from "@training-planner/planner-core";
import { childPlanVersion } from "./propose";

export interface OrientationReplanInput {
  /** The plan in force. Its past days are the boundary this proposal may not cross. */
  plan: PlanVersion;
  /** The folded profile (packages/domain's profileFromWizard), not the raw answers. */
  profile: AthleteProfile;
  /** History-derived evidence; the caller owns the derivation so this module stays pure. */
  evidence: Evidence;
  today: string;
  seed: string;
  knowledge: KnowledgeBundle;
  horizonDays?: number;
}

export interface OrientationReplanSummary {
  /** Changed days across the whole future window, not the truncated diff's count. */
  changes: number;
  /** Days where a session appears, disappears or moves to another weekday. */
  sessionsMoved: number;
  kmBefore: number;
  kmAfter: number;
  firstChangedDay: string | null;
}

export interface OrientationReplan {
  optionId: "replan-for-orientation";
  /** The candidate version. Staged by the caller; never active until the runner accepts. */
  version: PlanVersion;
  /** The stored diff: truncated at two changes, with `changeCountWithinLimit` telling the truth. */
  diff: PlanDiff;
  summary: OrientationReplanSummary;
  /** True when the proposal changes more than the review's two-change rule allows: it is not an edit. */
  exceedsReviewChangeLimit: boolean;
  /** Planner invariants the new version would violate. Empty is the only offerable state. */
  invariantViolations: string[];
}

const kmOf = (session: PlanVersion["sessions"][number]): number => session.distanceKm ?? 0;

export function proposeOrientationReplan(input: OrientationReplanInput): OrientationReplan {
  const { plan, profile, evidence, today, seed, knowledge } = input;
  const horizonDays = input.horizonDays ?? knowledge.number("review-triggers.yaml#horizon_days");

  const freezeDays = knowledge.number("review-triggers.yaml#freeze_window_days");
  const firstEditableDay = addDays(today, freezeDays);
  // The new block starts on a week boundary: a block that starts mid-week has a partial first week, and the
  // week-over-week ceiling cannot be honest about a partial week. Days before the boundary stay as the runner is
  // committed to them.
  const blockStart = weekStart(addDays(firstEditableDay, 6));

  const generated = generatePlan({
    profile,
    evidence,
    state: { planStartDay: blockStart, horizonDays },
    clock: { today },
    seed,
    knowledge,
  });

  // The past and the freeze window are kept exactly as the runner is committed to them: only days after the first
  // editable day come from the new plan. Without this, a re-plan would rewrite days the runner has already run or is
  // committed to, which ADR-0010 forbids.
  const kept = plan.sessions.filter((session) => session.day < blockStart);
  const fresh = generated.version.sessions.filter((session) => session.day >= blockStart);
  const sessions = [...kept, ...fresh].sort((left, right) => (left.day < right.day ? -1 : 1));
  const version = childPlanVersion(plan, sessions, today, "replan-for-orientation");

  const diff = diffPlans(plan, version, {
    createdAtDay: today,
    knowledgeHash: knowledge.hash,
    maxChanges: 2,
    reason: "orientation-changed",
    signalIds: [],
    expectedCost: "the block is re-cut for the new orientation",
    knobsUsed: ["review-triggers.yaml#freeze_window_days"],
  });

  // The honest count: compare every future day, not the truncated diff. A day on or before the old version's
  // generated day is frozen (the past), so it is excluded here exactly as diffPlans excludes it.
  const before = new Map(plan.sessions.filter((session) => session.day >= blockStart).map((session) => [session.day, session]));
  const after = new Map(version.sessions.filter((session) => session.day >= blockStart).map((session) => [session.day, session]));
  const days = [...new Set([...before.keys(), ...after.keys()])].sort();

  let changes = 0;
  let sessionsMoved = 0;
  let kmBefore = 0;
  let kmAfter = 0;
  let firstChangedDay: string | null = null;

  for (const day of days) {
    const oldSession = before.get(day);
    const newSession = after.get(day);
    kmBefore += oldSession === undefined ? 0 : kmOf(oldSession);
    kmAfter += newSession === undefined ? 0 : kmOf(newSession);
    const changed =
      oldSession === undefined ||
      newSession === undefined ||
      oldSession.kind !== newSession.kind ||
      kmOf(oldSession) !== kmOf(newSession) ||
      oldSession.summaryText !== newSession.summaryText;
    if (!changed) continue;
    changes += 1;
    if (firstChangedDay === null) firstChangedDay = day;
    if (oldSession === undefined || newSession === undefined || oldSession.kind !== newSession.kind) sessionsMoved += 1;
  }

  return {
    optionId: "replan-for-orientation",
    version,
    diff,
    summary: { changes, sessionsMoved, kmBefore, kmAfter, firstChangedDay },
    exceedsReviewChangeLimit: !diff.changeCountWithinLimit,
    invariantViolations: checkInvariants({ version, openQuestions: [] }, { knowledge }).map(
      (violation) => violation.invariant,
    ),
  };
}
